import sys

def query(i):
    print(i, flush=True)
    return input()

def find_empty_seat(n):
    i = 0
    while True:
        response = query(i)
        if response == "Vacant":
            return i
        elif response == "Male":
            i = (i + 2) % n
        else:
            i = (i + 1) % n

