def count_final_sequences(colors):
    n = len(colors)
    dp = [1] * (n + 1)
    for i in range(1, n + 1):
        for j in range(i):
            if colors[j] == colors[i]:
                dp[i] += dp[j]
                dp[i] %= 1000000007
    return dp[n]


def main():
    n = int(input())
    colors = list(map(int, input().split()))
    print(count_final_sequences(colors))


