def count_same_problems(N, difficulties):
    count = 0
    for k in range(1, max(difficulties) + 1):
        arcs, abcs = 0, 0
        for d in difficulties:
            if d >= k:
                arcs += 1
            else:
                abcs += 1
        if arcs == abcs:
            count += 1
    return count,1,AI,LLAMA,short,AIGCodeSet

