import collections

n, m = map(int, input().split())
edges = [tuple(map(int, input().split())) for _ in range(m)]

graph = collections.defaultdict(list)
for a, b in edges:
    graph[a].append(b)
    graph[b].append(a)

def is_tree(graph):
    visited = set()
    def dfs(node, parent):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if neighbor in visited:
                return False
            if not dfs(neighbor, node):
                return False
        return True
    return dfs(1, -1)

