def is_isomorphic(s, t):
    if len(s) != len(t):
        return False
    for i in range(len(s)):
        if s[i] != t[i] and s[i] in t:
            return False
    return True

def is_in_normal_form(s):
    for i in range(len(s)):
        for j in range(i+1, len(s)):
            if s[i] != s[j] and s[i] < s[j]:
                return False
    return True

def get_normal_form_strings(N):
    result = []
    for i in range(1 << N):
        s = ""
        for j in range(N):
            if i & (1 << j):
                s += "a"
            else:
                s += "b"
        if is_isomorphic(s, s[::-1]) and is_in_normal_form(s):
            result.append(s)
    return result

def main():
    N = int(input())
    result = get_normal_form_strings(N)
    print(*result, sep="\n")

if __name__ == "__main__":
    main(),1,AI,LLAMA,medium,AIGCodeSet

