from collections import defaultdict


def main():
    N, M, P = map(int, input().split())
    E = [[] for _ in range(N)]
    d = defaultdict(int)
    for _ in range(M):
        a, b, c = map(int, input().split())
        a, b = a-1, b-1
        d[(a, b)] = c - P
        E[a].append(b)

    INF = 10**14 * 2
    V = [INF] * N
    V[0] = 0
    for _ in range(N - 1):
        for e in d:
            s, t = e
            if V[s] + d[e] < V[t]:
                V[t] = V[s] + d[e]
    ans = V[N - 1]
    for _ in range(N - 1):
        for e in d:
            s, t = e
            if V[s] + d[e] < V[t]:
                V[t] = V[s] + d[e]
    if V[N - 1] < ans:
        print(-1)
        return
    print(max(-ans, 0))

if __name__ == '__main__':
    main(),1,AI,CODESTRAL,medium,AIGCodeSet

