    print(1)
else:
    def cal(xy):
        dis = [0] * (n - 1)
        a, b = xy[0]
        for idx, (x, y) in enumerate(xy[1:]):
            dis[idx] = (x - a, y - b)
            a, b = x, y
        dis_count = {}
        for d in dis:
            if d in dis_count:
                dis_count[d] += 1
            else:
                dis_count[d] = 1
        max_count = 0
        for count in dis_count.values():
            max_count = max(max_count, count)
        return n - max_count
    print(min(cal(xy), cal(sorted(xy, key=lambda x: x[1])))),1,AI,CODESTRAL,medium,AIGCodeSet

