def get_min_sum(a_list):
    n = len(a_list)
    b_list = [1] * n
    for i in range(n):
        for j in range(i+1, n):
            if a_list[i] * b_list[i] > a_list[j] * b_list[j]:
                b_list[j] = a_list[i] * b_list[i] // a_list[j]
    return sum(b_list) % (10**9 + 7),1,AI,LLAMA,short,AIGCodeSet

