def solve(A, B):
    if A == B:
        return "IMPOSSIBLE"
    if A < B:
        smaller = A
        larger = B
    else:
        smaller = B
        larger = A
    for i in range(smaller, larger+1):
        if abs(A-i) == abs(B-i):
            return i
    return "IMPOSSIBLE",1,AI,LLAMA,short,AIGCodeSet

