import random

def min_final_health(N, A):
    alive = [i for i in range(N)]
    while len(alive) > 1:
        attacker = random.choice(alive)
        defender = random.choice(alive)
        while defender == attacker:
            defender = random.choice(alive)
        A[defender] -= A[attacker]
        if A[defender] <= 0:
            alive.remove(defender)
    return min(A)

