def get_max_equal_elems(p, x, y):
    n = len(p)
    max_count = 0
    for i in range(n):
        if p[i] == i + 1:
            max_count += 1
    for j in range(len(x)):
        p[x[j] - 1], p[y[j] - 1] = p[y[j] - 1], p[x[j] - 1]
        count = 0
        for i in range(n):
            if p[i] == i + 1:
                count += 1
        max_count = max(max_count, count)
    return max_count


