def get_median(arr):
    n = len(arr)
    if n % 2 == 0:
        return (arr[n//2 - 1] + arr[n//2])/2
    else:
        return arr[n//2]

def get_median_excluding(arr, x):
    return get_median(arr[:x-1] + arr[x:])

def get_median_values(arr):
    return [get_median_excluding(arr, i+1) for i in range(len(arr))]

