from collections import deque
def main():
    #入力
    readline=stdin.readline
    n=int(readline())
    m=n*(n-1)//2
    a=[list(map(lambda x:int(x)-1,readline().split())) for _ in range(n)]
    d=dict()
    cnt=0
    for i in range(n-1):
        for j in range(i+1,n):
            d[(i,j)]=cnt
            d[(j,i)]=cnt
            cnt+=1

    G1=[[] for _ in range(m)]
    G2=[set() for _ in range(m)]
    for i in range(n):
        for j in range(n-1-1):
            k=d[(i,a[i][j])]
            l=d[(i,a[i][j+1])]
            G1[k].append(l)
            G2[l].add(k)

    now=[]
    for i in range(m):
        if len(G2[i])==0:
            now.append(i)

    if len(now)==0:
        print(-1)
    else:
        #トポロジカルソート
        t=[]
        nex=deque(now)
        while len(nex)>0:
            now=nex.popleft()
            t.append(now)
            li=G1[now]
            for i in li:
                G2[i].remove(now)
                if len(G2[i])==0:
                    nex.append(i)

        if len(t)!=m:
            print(-1)
        else:
            dp=[0]*m
            dp[t[0]]=1
            for i in t:
                for j in G1[i]:
                    dp[j]=max(dp[j],dp[i]+1)

            print(max(dp))

