def solve(N, S, Q, queries):
    result = []
    for query in queries:
        if query[0] == 1:
            i, c = query[1], query[2]
            if S[i] != c:
                S = S[:i] + c + S[i+1:]
        else:
            l, r = query[1], query[2]
            substr = S[l-1:r]
            result.append(len(set(substr)))
    return result

def main():
    N, S = input().split()
    N = int(N)
    Q = int(input())
    queries = []
    for i in range(Q):
        query = list(map(int, input().split()))
        queries.append(query)
    result = solve(N, S, Q, queries)
    for res in result:
        print(res)

