    for j in range(i, N):
        if i!= j:
            T[(i, j)] = A[i][j]

T = sorted(T.items(), key = lambda x:x[1], reverse=True)

def dijkstra(V, start, Cost):
    routes = [float("inf")]*V
    routes[start] = 0
    minHeap = []
    used = [0]*V
    heapq.heappush(minHeap, (0, start))

    while minHeap:
        (c, current) = heapq.heappop(minHeap)
        if used[current] == 0:
            used[current] = 1
            for road in range(V):
                if Cost[current][road]!= -1:
                    if routes[road] > c + Cost[current][road]:
                        routes[road] = c + Cost[current][road]
                        heapq.heappush(minHeap, (c + Cost[current][road], road))
    return routes

Cost = [[-1]*N for _ in range(N)]
ans = 0
for i in range(N):
    D, c = T[i]
    x, y = D
    Cost[x][y] = c
    Cost[y][x] = c
    ans += c

for i in range(N):
    P = dijkstra(N, i, Cost)
    for j in range(N):
        if P[j]!= A[i][j]:
            print(-1)
            sys.exit()

for i in range(N):
    D, c = T[i]
    x, y = D
    Cost[x][y] = -1
    Cost[y][x] = -1
    P_1 = dijkstra(N, x, Cost)
    P_2 = dijkstra(N, y, Cost)
    n = 0
    for j in range(N):
        if P_1[j]!= A[x][j] or P_2[j]!= A[y][j]:
            Cost[x][y] = c
            Cost[y][x] = c
            n = 1
            break
    if n == 0:
        ans -= c
