def coprime(nums):
    if len(nums) == 2:
        return gcd(nums[0], nums[1]) == 1
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if gcd(nums[i], nums[j]) != 1:
                return False
    return True

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def solve(nums):
    if coprime(nums):
        return "pairwise coprime"
    elif coprime([nums[0]] + nums[1:]):
        return "setwise coprime"
    else:
        return "not coprime"

