from fractions import gcd

def create_primeNum(N):
    if N == 1:
        return 1
    primeNum = 1
    for k in range(2, N + 1):
        # 2以外の偶数は素数ではないので無視する
        if k % 2 == 0 and k != 2:
            continue
        if pow(2, k - 1, k) == 1:
            primeNum += 1
    return primeNum

if __name__ == "__main__":
    a, b = map(int, input().split())
    N = gcd(a, b)
    print(create_primeNum(N)),1,AI,LLAMA,medium,AIGCodeSet

from collections import defaultdict

def prime_factorization(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def count_shichi_go_numbers(n):
    factor_count = defaultdict(int)
    for i in range(2, n + 1):
        factors = prime_factorization(i)
        for factor in factors:
            factor_count[factor] += 1

    shichi_go_count = 1
    for count in factor_count.values():
        shichi_go_count *= (count + 1)

    return shichi_go_count // 2

n = int(input())
print(count_shichi_go_numbers(n)),1,AI,CODESTRAL,medium,AIGCodeSet

