h = list(map(int, input().split()))

n = len(h)
dp =[[-2] * 2 for i in range(n)]


def f(index, is_sub):
    if(dp[index][is_sub] != -2):
        return dp[index][is_sub]

    v = h[index] - is_sub
    if(index == 0):
        dp[index][is_sub] = v
        return dp[index][is_sub]

    pre_v = f(index-1, 0)
    if(pre_v != -1 and pre_v <= v):
        dp[index][is_sub] = v
    pre_v = f(index-1, 1)
    if(pre_v != -1 and pre_v <= v):
        dp[index][is_sub] = v

    if(dp[index][is_sub]!=v):
        dp[index][is_sub] = -1

    #print(dp)
    return dp[index][is_sub]


