from itertools import permutations

def min_days_same_cake(cake_types):
    min_days = float('inf')
    for perm in permutations(cake_types):
        days = 0
        for i in range(len(perm) - 1):
            if perm[i] == perm[i + 1]:
                days += 1
        min_days = min(min_days, days)
    return min_days

