import sys
mod = 10**9 + 7

def count_sequences(n, m):
    dp = [0] * (m + 1)
    dp[1] = 1
    for i in range(2, m + 1):
        for j in range(1, i + 1):
            if i % j == 0:
                dp[i] = (dp[i] + dp[i // j]) % mod
    return dp[m]

