import math

def is_prime(n):
  if n <= 1:
    return False
  for i in range(2, int(math.sqrt(n)) + 1):
    if n % i == 0:
      return False
  return True

def count_similar(l, r):
  count = 0
  for i in range(l, r + 1, 2):
    if is_prime(i) and is_prime((i + 1) // 2):
      count += 1
  return count

