def main():
    n, k, c = MI()
    s = SI()
    ll = [0] * n
    rr = [0] * n
    for i, m in enumerate(s):
        if m == "o":
            if i - c - 1 >= 0:
                ll[i] = ll[i - c - 1] + 1
            else:
                ll[i] = 1
        else:
            ll[i] = ll[i - 1]
    #print(ll)
    for i in range(n - 1, -1, -1):
        m = s[i]
        if m == "o":
            if i + c + 1 < n:
                rr[i] = rr[i + c + 1] + 1
            else:
                rr[i] = 1
        else:
            rr[i] = rr[(i + 1) % n]
    #print(rr)
    ans = []
    if rr[1] < k:
        ans.append(1)
    for i in range(1, n - 1):
        if ll[i - 1] + rr[i + 1] < k:
            ans.append(i + 1)
