def is_bracket_sequence(strings):
    stack = []
    for string in strings:
        for char in string:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack:
                    return False
                stack.pop()
    return not stack,1,AI,LLAMA,short,AIGCodeSet

