def DepthFirst_search(S, pre):
    global out
    # print(pre)
    # print(out)
    if len(S) == 1:
        for i in range(len(pre)):
            if i == len(pre) - 1:
                out += pre[i] * 10 + int(S[0]) + pre[i] + int(S[0])
            else:
                out += 2 * pre[i]
        return False

    pre.append(int(S[0]))
    if DepthFirst_search(S[1:len(S):], pre):
        return False
    pre.pop()
    if len(pre) != 0:
        pre.append(pre.pop() * 10 + int(S[0]))
        if DepthFirst_search(S[1:len(S):], pre):
            return False

    return False

