from math import inf

def solve(D, G, p, c):
    dp = [[inf] * (G + 1) for _ in range(D + 1)]
    dp[0][0] = 0
    for i in range(1, D + 1):
        for j in range(G + 1):
            dp[i][j] = min(dp[i - 1][j], dp[i - 1][max(0, j - 100 * i)] + c[i - 1])
    return dp[D][G]

