import heapq

n = int(input())
numbers = list(map(int, input().split()))

left_heap = []
right_heap = []
medians = []

for i in range(n):
    if not left_heap or numbers[i] < -heapq.heappop(left_heap):
        heapq.heappush(left_heap, -numbers[i])
    else:
        heapq.heappush(right_heap, numbers[i])

    if len(left_heap) > len(right_heap) + 1:
        heapq.heappush(right_heap, -heapq.heappop(left_heap))
    elif len(right_heap) > len(left_heap):
        heapq.heappush(left_heap, -heapq.heappop(right_heap))

    if i >= n // 2:
        medians.append(-left_heap[0])

for i in range(n // 2):
    medians.append(medians[i])

for median in medians:
    print(median),1,AI,CODESTRAL,medium,AIGCodeSet

def resolve():
    '''
    code here
    '''
    N, K = [int(item) for item in input().split()]
    R, S, P= [int(item) for item in input().split()]
    T = input()
    path_num = min(K, N-K)
    memo = [1 for _ in range(path_num)]
    def point_chk(s):
        if s == 'r':
            return P
        elif s == 's':
            return R
        elif s == 'p':
            return S
        else:
            raise


    max_point = 0
    for i, s in enumerate(T):
        if i < K:
            max_point += point_chk(s)
            memo[i%path_num] = s
        else:
            if s == memo[i%K]:
                pass
            else:
                memo[i%K] = s
                max_point += point_chk(s)
        # print(i, s, memo, max_point)

    print(max_point)

if __name__ == "__main__":
    resolve(),1,AI,GEMINI,medium,AIGCodeSet

