def get_max_sum(dequeue, k):
    n = len(dequeue)
    if n == 0 or k == 0:
        return 0
    if n == 1:
        return dequeue[0]
    if k == 1:
        return max(dequeue[0], dequeue[-1])
    if k == 2:
        return max(dequeue[0] + dequeue[1], dequeue[-1] + dequeue[-2])

    left_sum = 0
    right_sum = 0
    for i in range(1, n - 1):
        left_sum += dequeue[i]
        right_sum += dequeue[-i]

    return max(left_sum, right_sum),1,AI,LLAMA,medium,AIGCodeSet

