def get_happiness(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 1, n):
            dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    return dp[0][n - 1]


