def sieve_of_eratosthenes(n):
    primes = [True] * (n + 1)
    primes[0] = primes[1] = False
    for i in range(2, int(n**0.5) + 1):
        if primes[i]:
            for j in range(i*i, n + 1, i):
                primes[j] = False
    return primes

def count_similar_to_2017(l, r, primes):
    count = 0
    for x in range(l, r + 1, 2):
        if primes[x] and primes[(x + 1) // 2]:
            count += 1
    return count

