def get_max_divisors(a, b):
    divisors = []
    for i in range(1, int(a**0.5) + 1):
        if a % i == 0:
            divisors.append(i)
            if a // i != i:
                divisors.append(a // i)
    for i in range(1, int(b**0.5) + 1):
        if b % i == 0:
            if i not in divisors:
                divisors.append(i)
                if b // i != i and b // i not in divisors:
                    divisors.append(b // i)
    return len(divisors),1,AI,LLAMA,medium,AIGCodeSet

