def get_min_cost(N, M_a, M_b, a, b, c):
    min_cost = float('inf')
    for i in range(N):
        for j in range(i+1, N):
            if a[i] * M_b == b[j] * M_a:
                cost = c[i] + c[j]
                if cost < min_cost:
                    min_cost = cost
    if min_cost == float('inf'):
        return -1
    else:
        return min_cost


