from collections import deque

def solve():
    n = int(input())
    graph = [list(map(int, input().split())) for _ in range(n)]
    degree = [0] * n
    for i in range(n):
        for j in range(n - 1):
            degree[graph[i][j] - 1] += 1

    queue = deque([i for i in range(n) if degree[i] == 1])
    result = [0] * n
    day = 0

    while queue:
        day += 1
        for _ in range(len(queue)):
            u = queue.popleft()
            result[u] = day
            for v in graph[u]:
                v -= 1
                degree[v] -= 1
                if degree[v] == 1:
                    queue.append(v)

    if any(degree):
        return -1

    return max(result)

print(solve()),1,AI,CODESTRAL,medium,AIGCodeSet

