def xor(a, b):
    return a ^ b

def check_condition(a, k):
    for i in range(len(a)):
        for j in range(i+1, len(a)):
            if a[i] == a[j]:
                if xor(a[i], a[i+1], ..., a[j]) != k:
                    return False
    return True

def find_sequence(k, m):
    a = []
    for i in range(2**(m+1)):
        a.append(i)
    if check_condition(a, k):
        return a
    else:
        return None

