def paint_dominoes(N, S1, S2):
    MOD = 1000000007
    dp = [[0] * (N + 1) for _ in range(3)]
    dp[0][0] = 1
    for i in range(N):
        for j in range(3):
            for k in range(3):
                if j != k:
                    dp[j][i + 1] += dp[k][i]
                    dp[j][i + 1] %= MOD
    return dp[0][N] + dp[1][N] + dp[2][N]

def main():
    N = int(input())
    S1 = input()
    S2 = input()
    print(paint_dominoes(N, S1, S2))

