def get_min_bricks_to_break(arr):
    n = len(arr)
    if n == 1:
        return 0
    if n == 2:
        return 1
    dp = [0] * (n + 1)
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + 1
        for j in range(i - 2, -1, -1):
            if arr[j] == i - j:
                dp[i] = min(dp[i], dp[j] + 1)
                break
    return dp[n]


def main():
    n = int(input())
    arr = list(map(int, input().split()))
    print(get_min_bricks_to_break(arr))


