def staircase_climbing(n, m, a):
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if i - j not in a:
                dp[i] += dp[i - j]
                dp[i] %= 1000000007
    return dp[n]


def main():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    print(staircase_climbing(n, m, a))


