def get_satisfaction_points(dishes, satisfaction, bonuses):
    points = 0
    for i in range(len(dishes)):
        points += satisfaction[dishes[i] - 1]
        if i < len(dishes) - 1:
            points += bonuses[dishes[i] - 1]
    return points

