def get_min_cost(a, b, m, tickets):
    min_cost = float('inf')
    for i in range(m):
        cost = tickets[i][2]
        for j in range(a):
            if j == tickets[i][0] - 1:
                cost += a[j]
            if j == tickets[i][1] - 1:
                cost += b[j]
        min_cost = min(min_cost, cost)
    return min_cost


