def check_equal(a, b):
    if len(a) != len(b):
        return False
    for i in range(len(a)):
        if a[i] != b[i]:
            return False
    return True


def solve(a, b):
    if check_equal(a, b):
        return "Yes"

    for i in range(len(a)):
        for j in range(len(b)):
            if a[i] + 2 == b[j] and b[j] + 1 == a[i]:
                a[i] += 2
                b[j] += 1
                if check_equal(a, b):
                    return "Yes"
    return "No"


