def count_hat_combinations(n, a):
    MOD = 1000000007
    dp = [1] * (n + 1)
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if a[i - 1] >= j:
                dp[i] += dp[i - j]
                dp[i] %= MOD
    return dp[n]


