from fractions import gcd

def create_primeNum(N):
    if N == 1:
        return 1
    primeNum = 1
    for k in range(2, N + 1):
        # 2以外の偶数は素数ではないので無視する
        if k % 2 == 0 and k!= 2:
            continue
        if pow(2, k - 1, k) == 1:
            primeNum += 1
    return primeNum

def count_coprime_divisors(a, b):
    g = gcd(a, b)
    prime_factors = set()
    i = 2
    while i * i <= g:
        if g % i:
            i += 1
        else:
            g //= i
            prime_factors.add(i)
    if g > 1:
        prime_factors.add(g)
    return len(prime_factors)

if __name__ == "__main__":
    a, b = map(int, input().split())
    print(count_coprime_divisors(a, b)),1,AI,CODESTRAL,medium,AIGCodeSet

import sys

MOD = 10**9 + 7

def max_product(N, K, A):
    A.sort()
    negatives = [x for x in A if x < 0]
    positives = [x for x in A if x >= 0]
    zeros = [x for x in A if x == 0]
    if K % 2 == 1:
        if not positives:
            return negatives[-K]
        if not negatives:
            return positives[-K]
        if negatives[-1] * negatives[-2] > positives[-1]:
            return negatives[-K]
        else:
            return positives[-K]
    else:
        if not negatives or len(negatives) < K:
            return 0
        if K - len(zeros) <= len(negatives):
            return negatives[-K] * negatives[-K + 1] % MOD
        else:
            return 0

def main():
