def solve(N, A):
    count = 0
    for length in range(1, N + 1):
        for start in range(N - length + 1):
            end = start + length
            xor_val = A[start]
            sum_val = A[start]
            for i in range(start + 1, end):
                xor_val ^= A[i]
                sum_val += A[i]
            if xor_val == sum_val:
                count += 1
    return count

