def solve(N, S, A):
    MOD = 998244353
    dp = [0] * (N + 1)
    for i in range(1, N + 1):
        for j in range(S + 1):
            if j - A[i - 1] >= 0:
                dp[j] = (dp[j] + dp[j - A[i - 1]]) % MOD
    return sum(dp) % MOD,1,AI,LLAMA,short,AIGCodeSet

import bisect

def longest_increasing_subsequence(sequence):
    lis = []
    for num in sequence:
        index = bisect.bisect_left(lis, num)
        if index == len(lis):
            lis.append(num)
        else:
            lis[index] = num
    return len(lis)

