from collections import defaultdict

def solve(n, m, edges):
    graph = defaultdict(list)
    for a, b, c in edges:
        graph[a].append((b, c))

    dp = [float('-inf')] * (n + 1)
    dp[1] = 0

    for i in range(1, n + 1):
        for j, c in graph[i]:
            dp[j] = max(dp[j], dp[i] + c)

    if dp[n] == float('-inf'):
        return 'inf'
    return dp[n]

