@lru_cache(maxsize=None)
def dp(cur,i):
	if cur==N:
		if i==3:
			return 1
		else:
			return 0
	else:
		if S[cur]=='A' and i==0:
			return (dp(cur+1,i+1)+dp(cur+1,i))%mod
		elif S[cur]=='B' and i==1:
			return (dp(cur+1,i+1)+dp(cur+1,i))%mod
		elif S[cur]=='C' and i==2:
			return (dp(cur+1,i+1)+dp(cur+1,i))%mod
		elif S[cur]=='?' and i!=3:
			return (dp(cur+1,i+1)+3*dp(cur+1,i))%mod
		elif S[cur]=='?':
			return 3*dp(cur+1,i)%mod
		else:
			return dp(cur+1,i)%mod

