def find_max_substring_length(s):
    n = len(s)
    max_len = 0
    for len in range(1, n // 2 + 1):
        for i in range(n - len + 1):
            for j in range(i + len, n - len + 1):
                if s[i:i + len] == s[j:j + len]:
                    max_len = max(max_len, len)
    return max_len

