def is_similar_to_2017(n):
    if n % 2 == 0:
        return False
    if n == 2017:
        return True
    return is_prime(n) and is_prime((n + 1) // 2)

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def count_similar_to_2017(l, r):
    count = 0
    for i in range(l, r + 1):
        if is_similar_to_2017(i):
            count += 1
    return count

