    n, m = map(int, input().split())
    submissions = []
    for i in range(m):
        problem_id, verdict = input().split()
        submissions.append((int(problem_id), verdict))
    correct_answers, penalties = get_correct_answers_and_penalties(submissions)
    print(correct_answers, penalties)


