from functools import lru_cache
@lru_cache(None)
def dfs(fukasa, ansuka1):
    if fukasa == 0:
        if ans[0] == 1:
            return True
        else:
            return False

    mi = max(a[fukasa] - ansuka1 // 2, 0)
    ans[fukasa] = mi
    if not dfs(fukasa - 1, ansuka1):
        return False

    tmp = a[fukasa] + ansuka1
    tmp = min(tmp, 2 ** fukasa)

    while tmp >= mi:
        if dfs(fukasa - 1, tmp):
            ans[fukasa] = tmp
            break
        tmp -= 1
    else:
        return False
    return True

