import sys

def min_fatigue(N, A, B, X):
    min_fatigue_level = 0
    current_position = 1

    for i in range(1, N):
        distance_walk = X[i] - X[current_position]
        distance_teleport = X[i] - X[i-1]

        if A * distance_walk <= B:
            min_fatigue_level += A * distance_walk
            current_position = i
        else:
            min_fatigue_level += B

    return min_fatigue_level

