from collections import Counter

def min_operations(s, k):
    n = len(s)
    counter = Counter(s)
    max_freq = max(counter.values())

    if max_freq * 2 <= n * k:
        return 0

    if n == 1:
        return k

    if n == 2:
        return (k + 1) // 2

    return k - (k // 2) * (max_freq - (n + 1) // 2)

