def is_palindrome(s):
    return s == s[::-1]

def min_operations(s):
    if is_palindrome(s):
        return 0

    min_ops = float('inf')
    for i in range(len(s)):
        if is_palindrome(s[:i] + s[i+1:]):
            min_ops = min(min_ops, 1 + min_operations(s[:i] + s[i+1:]))

    return min_ops if min_ops != float('inf') else -1,1,AI,LLAMA,short,AIGCodeSet

