    ls[0] = False
    cnt = 0
    for i in range(len(ls)):
        if ls[i]:
            if a % i == 0 and b % i == 0:
                cnt += 1
            if i != 1:
                for j in range(i * i, len(ls), i):
                    if ls[j]:
                        ls[j] = False
    print(cnt)


