def solve(n, v):
    count1 = [0] * (10**5 + 1)
    count2 = [0] * (10**5 + 1)

    for i in range(n):
        if i % 2 == 0:
            count1[v[i]] += 1
        else:
            count2[v[i]] += 1

    max_count1 = max(count1)
    max_count2 = max(count2)

    return n - max(max_count1, max_count2)

