BIT = [{"a": 0, "b": 0, "c": 0, "d": 0, "e": 0,
        "f": 0, "g": 0, "h": 0, "i": 0, "j": 0,
        "k": 0, "l": 0, "m": 0, "n": 0, "o": 0,
        "p": 0, "q": 0, "r": 0, "s": 0, "t": 0,
        "u": 0, "v": 0, "w": 0, "x": 0, "y": 0, "z": 0} for _ in range(N + 1)]  # 初期化


def add(A, B):
    for k in A.keys():
        A[k] += B[k]
    return A


def sub(A, B):
    for k in A.keys():
        A[k] -= B[k]
    return A


def count(A):
    return 26 - list(A.values()).count(0)


def identify(i):
    d = sub(sum(i),sum(i-1))
    for k,v in d.items():
        if v == 1:
            return k

# 初期化
for j in range(N):

    i = j + 1
    while i <= N:
        BIT[i][S[j]] += 1
        i += (i & -i)


# 文字の交換
def change(i, c, char):

    global BIT, N

    while i < N:
        BIT[i][char] -= 1
        BIT[i][c] += 1
        i += (i & -i)


# 文字数の取り出し
def sum(i):

    global BIT, N

    _sum = {"a": 0, "b": 0, "c": 0, "d": 0, "e": 0,
            "f": 0, "g": 0, "h": 0, "i": 0, "j": 0,
            "k": 0, "l": 0, "m": 0, "n": 0, "o": 0,
            "p": 0, "q": 0, "r": 0, "s": 0, "t": 0,
            "u": 0, "v": 0, "w": 0, "x": 0, "y": 0, "z": 0}
    while i > 0:
        _sum = add(_sum, BIT[i])
        i -= (i & -i)

    return _sum


