    min_attacks = 0
    for i in range(len(katanas)):
        if katanas[i][0] >= total_damage:
            min_attacks += 1
            total_damage -= katanas[i][0]
        elif katanas[i][1] >= total_damage:
            min_attacks += 2
            total_damage -= katanas[i][1]
    return min_attacks

