#!/usr/bin/env python3
import sys
from itertools import combinations


def gen_step(s, n):
    # 和がsとなるn個の非負整数列
    # a1 + a2 + ... + an = s
    if n == 0:
        yield []
        return
    if n == 1:
        yield [s]
        return
    for i in range(s + 1):
        for step in gen_step(s - i, n - 1):
            yield [i] + step


def solve(N: int, M: int, Q: int, a: "List[int]", b: "List[int]", c: "List[int]", d: "List[int]"):
    ans = 0
    for s in range(M):
        for steps in gen_step(s, N - 1):
            ret = 0
            A = [1] * N
            for i, step in enumerate(steps):
                A[i + 1] = A[i] + step
            for q in range(Q):
                if A[b[q] - 1] - A[a[q] - 1] == c[q]:
                    ret += d[q]
            ans = max(ans, ret)
    print(ans)
    return


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word

    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    M = int(next(tokens))  # type: int
    Q = int(next(tokens))  # type: int
    a = [int()] * (Q)  # type: "List[int]"
    b = [int()] * (Q)  # type: "List[int]"
    c = [int()] * (Q)  # type: "List[int]"
    d = [int()] * (Q)  # type: "List[int]"
    for i in range(Q):
        a[i] = int(next(tokens))
        b[i] = int(next(tokens))
        c[i] = int(next(tokens))
        d[i] = int(next(tokens))
    solve(N, M, Q, a, b, c, d)


if __name__ == "__main__":
