def abc_number(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(i + 1, n + 1):
            for k in range(j + 1, n + 1):
                if s[i] == 'A' and s[j] == 'B' and s[k] == 'C':
                    dp[i][j] += 1
                    dp[j][k] += 1
                    dp[k][n] += 1
    return dp[0][n]

def solve(s):
    q = s.count('?')
    result = 0
    for i in range(3**q):
        t = list(s)
        for j in range(q):
            t[s.index('?', j)] = ['A', 'B', 'C'][i // 3**(q - j - 1) % 3]
        result += abc_number(''.join(t))
    return result % (10**9 + 7)

def main():
    s = input()
    print(solve(s))

if __name__ == "__main__":
