def solve(T):
    n = len(T)
    dp = [[0, 0] for _ in range(n + 1)]
    for i in range(n):
        if T[i] == 'D':
            dp[i + 1][0] = dp[i][0] + 1
            dp[i + 1][1] = dp[i][1]
        elif T[i] == 'P':
            dp[i + 1][0] = dp[i][0]
            if i > 0 and T[i - 1] == 'D':
                dp[i + 1][1] = dp[i][1] + 1
            else:
                dp[i + 1][1] = dp[i][1]
        else:
            dp[i + 1][0] = max(dp[i][0] + 1, dp[i][0])
            if i > 0 and T[i - 1] == 'D':
                dp[i + 1][1] = max(dp[i][1] + 1, dp[i][1])
            else:
                dp[i + 1][1] = max(dp[i][1], dp[i][1])
    ans = []
    i = n
    while i > 0:
        if T[i - 1] == '?':
            if dp[i][0] > dp[i - 1][0]:
                ans.append('D')
            else:
                ans.append('P')
            i -= 1
        else:
            ans.append(T[i - 1])
            i -= 1
    return ''.join(ans[::-1])


