import sys

def bellman_ford(edges, num_vertices):
    distances = [float('-inf')] * num_vertices
    distances[0] = 0

    for _ in range(num_vertices - 1):
        for u, v, w in edges:
            if distances[u] + w > distances[v]:
                distances[v] = distances[u] + w

    for u, v, w in edges:
        if distances[u] + w > distances[v]:
            return float('inf')

    return distances[-1]

