import numpy as np

def main():
    H, W, K = map(int, raw_input().split())
    S = []

    for i in range(H):
        S.append(list(raw_input()))

    for i in range(H):
        for j in range(W):
            S[i][j] = int(S[i][j])

    ans = 10**9

    for divide in range(2**(H-1)):
        regions = []
        for l in range(H):
            if divide & 1 << l:
                regions.append(l+1)
        S_subs = []
        prev = 0
        for region in regions:
            new = region
            S_subs.append(S[prev:new])
            prev = new
        S_subs.append(S[prev:H])
        N = len(S_subs)

        count = [0]*N

        bin_num = bin(divide)[2:]

        ans_temp = 0
        for i in bin_num:
            ans_temp += int(i)

#        print "--"                                                                                                    
#        print ans_temp                                                                                                
        for j in range(W):
            for l in range(N):
                for item in S_subs[l]:
                    count[l] += item[j]
            if max(count) > K:
                ans_temp = ans_temp + 1
                count = [0]*N
        if ans_temp < ans:
            ans = ans_temp

#        print ans_temp                                                                                                
    print ans

