def min_watering_operations(h):
    n = len(h)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = min(dp[i - 1] + 1, dp[i])
        for j in range(i):
            if h[j] <= h[i - 1]:
                dp[i] = min(dp[i], dp[j] + 1)
    return dp[n],1,AI,LLAMA,short,AIGCodeSet

