def countt(n, hani, kumi):
    an = 0
    for i in range(0, n - 1):
        if hani[i] == 1:
            if kumi[n - i - 2] == -1:
                kumi = countt(n - i - 1, hani, kumi)
            an += kumi[n - i - 2]
    kumi[n - 1] = an
