import heapq

def shortest_path(n, m, s):
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    prev = [-1] * (n + 1)
    q = [(0, 0)]

    while q:
        dist, u = heapq.heappop(q)
        if dist > dp[u]:
            continue
        for i in range(1, m + 1):
            v = u + i
            if v > n or s[v] == '1':
                continue
            if dp[v] > dp[u] + 1:
                dp[v] = dp[u] + 1
                prev[v] = u
                heapq.heappush(q, (dp[v], v))

    if dp[n] == float('inf'):
        return -1

    path = []
    u = n
    while u!= 0:
        path.append(u - prev[u])
        u = prev[u]
    return path[::-1]

n, m = map(int, input().split())
s = input()
result = shortest_path(n, m, s)
if result == -1:
    print(-1)
else:
