def count_sardines(n, a, b):
    mod = 1000000007
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j or a[i - 1] * a[j - 1] + b[i - 1] * b[j - 1] != 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = dp[i - 1][j - 1]
    return dp[n][n] % mod

