def count_pairs(grid):
    H, W = len(grid), len(grid[0])
    black_squares = []
    white_squares = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                black_squares.append((i, j))
            else:
                white_squares.append((i, j))
    pairs = 0
    for c1 in black_squares:
        for c2 in white_squares:
            if is_valid_path(grid, c1, c2):
                pairs += 1
    return pairs

def is_valid_path(grid, c1, c2):
    H, W = len(grid), len(grid[0])
    i, j = c1[0], c1[1]
    while i != c2[0] or j != c2[1]:
        if i < 0 or i >= H or j < 0 or j >= W:
            return False
        if grid[i][j] == '#':
            i, j = i + 1, j
        else:
            i, j = i - 1, j
    return True

def main():
    H, W = map(int, input().split())
    grid = []
    for _ in range(H):
        grid.append(list(input()))
    print(count_pairs(grid))

