def is_possible(b):
    a = []
    for i in range(len(b)):
        if b[i] not in a:
            a.append(b[i])
        else:
            return False
    return True

def get_operations(b):
    operations = []
    for i in range(len(b)):
        if b[i] not in operations:
            operations.append(b[i])
    return operations

def main():
    n = int(input())
    b = list(map(int, input().split()))
    if is_possible(b):
        operations = get_operations(b)
        for operation in operations:
            print(operation)
    else:
        print(-1)

