def count_subsequences(s):
    n = len(s)
    dp = [0] * (n + 1)
    for i in range(n):
        for j in range(i, n):
            if s[i] != s[j]:
                dp[j + 1] += dp[i] + 1
                dp[j + 1] %= 1000000007
    return dp[n]


def main():
    n = int(input())
    s = input()
    print(count_subsequences(s))


