def is_xor_possible(hats):
    n = len(hats)
    for i in range(n):
        left = hats[i-1] if i > 0 else hats[n-1]
        right = hats[(i+1) % n]
        if left ^ right ^ hats[i] != hats[i]:
            return False
    return True


def main():
    n = int(input())
    hats = list(map(int, input().split()))
    if is_xor_possible(hats):
        print("Yes")
    else:
        print("No")


