def count_strings(n):
    mod = 10**9 + 7
    dp = [1] * (n + 1)
    for i in range(1, n + 1):
        for j in range(i):
            if i - j < 3:
                continue
            dp[i] += dp[j] * (4**(i - j - 1))
            dp[i] %= mod
    return dp[n]

