from collections import defaultdict

def min_cost(N, points):
    cost_dict = defaultdict(int)
    for x, y in points:
        cost_dict[(x, y)] += 1

    min_cost = float('inf')
    for p in range(-10**9, 10**9 + 1):
        for q in range(-10**9, 10**9 + 1):
            if p == 0 and q == 0:
                continue
            cost = 0
            for x, y in points:
                if (x - p, y - q) not in cost_dict:
                    cost += 1
                cost_dict[(x, y)] -= 1
                if cost_dict[(x, y)] == 0:
                    del cost_dict[(x, y)]
            min_cost = min(min_cost, cost)
            cost_dict = defaultdict(int)
            for x, y in points:
                cost_dict[(x, y)] += 1
    return min_cost

