import sys

def resolve():
    N = int(input())
    cnt = 0
    for i in range(1, N, 2):
        if is_8_factors(i):
            cnt += 1
    print(cnt)

def is_8_factors(n):
    nfactors = 2
    upper = n
    div = 3
    while True:
        if upper <= div:
            break
        if n % 3 == 0:
            nfactors += 2
            upper = n // 3
        div += 2

    return True if nfactors == 8 else False

if '__main__' == __name__:
    resolve(),0,Human,Human,medium,AIGCodeSet

import sys

def main():
    MOD = 10**9 + 7
    H, W, K = map(int, sys.stdin.readline().split())

    dp = [[0] * (W + 1) for _ in range(H + 1)]
    dp[0][0] = 1

    for h in range(1, H + 1):
        for w in range(W + 1):
            if w > 0:
                dp[h][w] = (dp[h][w] + dp[h - 1][w - 1]) % MOD
            if w < W:
                dp[h][w] = (dp[h][w] + dp[h - 1][w + 1]) % MOD
            dp[h][w] = (dp[h][w] + dp[h - 1][w] * (W - 1)) % MOD

    result = 0
    for w in range(K, W + 1):
        result = (result + dp[H][w]) % MOD

    print(result)

if __name__ == "__main__":
    main(),1,AI,CODESTRAL,medium,AIGCodeSet

