def find_kth_substring(s, k):
    substrings = set()
    for i in range(len(s)):
        for j in range(i, len(s)):
            substrings.add(s[i:j+1])
    substrings = sorted(list(substrings))
    return substrings[k-1]

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def find_kth_smallest(self, k):
        stack = []
        node = self.root
        while node:
            for char in sorted(node.children.keys()):
                stack.append((char, node.children[char]))
                if node.is_end_of_word:
                    k -= 1
                    if k == 0:
                        return ''.join([char for char, _ in stack])
                node = node.children[char]
            node = None
            while stack and stack[-1][1].is_end_of_word:
                stack.pop()
            if stack:
                _, node = stack.pop()

def find_kth_substring(s, k):
    trie = Trie()
    for i in range(len(s)):
        for j in range(i, len(s)):
            trie.insert(s[i:j+1])
    return trie.find_kth_smallest(k),1,AI,CODESTRAL,long,AIGCodeSet

