def xor(n1, n2):
    if n2 == "0":
        return n1
    elif n2 == "1":
        if n1 == "1":
            return "0"
        else:
            return "1"

def bitxor(n1, n2):
    bn1 = bin(n1)[2:]
    bn2 = bin(n2)[2:]
    if n1 < n2:
        bn1 = bn1.zfill(len(bn2))
    else:
        bn2 = bn2.zfill(len(bn1))

    n3 = [xor(b1, b2) for b1, b2 in zip(bn1, bn2)]
    n3 = "".join(n3)
    return int(n3, 2)

