def count_patties(N, X):
    if N == 0:
        return 1 if X >= 1 else 0
    elif X <= 2 ** (N - 1):
        return count_patties(N - 1, X)
    elif X <= 2 ** N + 2 ** (N - 1):
        return 2 ** (N - 1) + count_patties(N - 1, X - 2 ** N)
    else:
        return 2 ** N + count_patties(N - 1, X - 2 ** N - 2 ** (N - 1))

