import itertools

def create_graph(n, k):
    if k > n * (n - 1) // 2:
        return -1

    graph = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if k > 0:
                graph.append((i, j))
                k -= 1
            else:
                if i % 2 == 1:
                    graph.append((i, j))

    return graph

def main():
    n, k = map(int, input().split())
    graph = create_graph(n, k)

    if graph == -1:
        print(-1)
    else:
        print(len(graph))
        for edge in graph:
            print(*edge)

if __name__ == "__main__":
    main(),1,AI,CODESTRAL,medium,AIGCodeSet

import sys
from typing import List

def read_input() -> tuple:
    n, k = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))
    f = list(map(int, sys.stdin.readline().split()))
    return n, k, a, f

def binary_search(n: int, k: int, a: List[int], f: List[int]) -> int:
    left, right = 0, 10**18
    while left < right:
        mid = (left + right) // 2
        if is_possible(n, k, a, f, mid):
            right = mid
        else:
            left = mid + 1
    return left

def is_possible(n: int, k: int, a: List[int], f: List[int], limit: int) -> bool:
    count = 0
    for i in range(n):
        if a[i] * f[i] > limit:
            count += (a[i] * f[i] - limit + limit - 1) // limit
    return count <= k

def main() -> None:
    n, k, a, f = read_input()
    result = binary_search(n, k, a, f)
    print(result)

if __name__ == "__main__":
    main(),1,AI,CODESTRAL,medium,AIGCodeSet

def solve(s, t):
    if len(s) != len(t):
        return "No"
    count = {}
    for c in s:
        if c not in count:
            count[c] = 0
        count[c] += 1
    for c in t:
        if c not in count:
            return "No"
        count[c] -= 1
    for v in count.values():
        if v != 0:
            return "No"
    return "Yes"

s = input()
t = input()
print(solve(s, t)),1,AI,GEMINI,medium,AIGCodeSet

