right = 10 ** 9

# able(X) を、すべての丸太を X 以下の長さに切れる場合 1 , そうでない場合 0 を返す関数とする
# 二分探索によって、able(X) が 1 に切り替わる X 点を見つける


def able(x):
    count = 0
    for i in range(N):
        if A[i] % x:
            count += A[i] // x
        else:
            count += A[i] // x - 1

    if count <= K:
        return True
    else:
        return False


while left < right:
    mid = left + (right - left) // 2
    if able(mid):
        right = mid
    else:
        left = mid + 1

print(left),0,Human,Human,medium,AIGCodeSet

