def g(a, b):
    if b == 0:
        return a
    else:
        return g(b, a % b)

def gcdarr(arr):
    ans = arr[0]
    for val in arr:
        ans = g(ans, val)
    return ans

def lcm(a, b):
    return (a * b) // g(a, b)

def lcmarr(arr):
    ans = arr[0]
    for val in arr:
        ans = lcm(ans, val)
    return ans

