def get_ans():
    n = int(input().rstrip())
    dv = 1
    bit_list = []
    while n!= 0:
        tmp = n % (dv*2)
        if tmp == 0:
            bit_list.append("0")
        else:
            bit_list.append("1")
            n -= dv
        dv *= -2
    return "".join(reversed(bit_list))

