def count_numbers(N, K):
    def dfs(pos, tight, cnt):
        if pos == len(N):
            return cnt == K
        if not tight and dp[pos][cnt]!= -1:
            return dp[pos][cnt]
        res = 0
        limit = int(N[pos]) if tight else 9
        for i in range(limit + 1):
            res += dfs(pos + 1, tight and i == limit, cnt + (i > 0))
        if not tight:
            dp[pos][cnt] = res
        return res

    N = str(N)
    dp = [[-1] * (K + 1) for _ in range(len(N))]
    return dfs(0, True, 0)

