import sys

sys.setrecursionlimit(10**6)

def find_root(node, parent):
    if parent[node] == node:
        return node
    parent[node] = find_root(parent[node], parent)
    return parent[node]

def union(node1, node2, parent, rank):
    root1 = find_root(node1, parent)
    root2 = find_root(node2, parent)

    if root1 == root2:
        return

    if rank[root1] < rank[root2]:
        parent[root1] = root2
    elif rank[root1] > rank[root2]:
        parent[root2] = root1
    else:
        parent[root2] = root1
        rank[root1] += 1

def solve():
    n, m = map(int, input().split())
    p = list(map(int, input().split()))

    parent = [i for i in range(n + 1)]
    rank = [0] * (n + 1)

    for _ in range(m):
        x, y = map(int, input().split())
        union(x, y, parent, rank)

    cycle_sizes = [0] * (n + 1)
    for i in range(1, n + 1):
        root = find_root(i, parent)
        cycle_sizes[root] += 1

    result = 0
    for i in range(1, n + 1):
        if p[i - 1] == i or cycle_sizes[find_root(i, parent)] % 2 == 0:
            result += 1

    print(result)

