def tak_to_cell_n(n, k, segments):
    mod = 998244353
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(k):
            if segments[j][0] <= i <= segments[j][1]:
                dp[i] += dp[i - segments[j][0]]
                dp[i] %= mod
    return dp[n]


def main():
    n, k = map(int, input().split())
    segments = []
    for _ in range(k):
        segments.append(list(map(int, input().split())))
    print(tak_to_cell_n(n, k, segments))


