MOD = 10**9 + 7

def factorial(n):
    fact = [1]
    for i in range(1, n+1):
        fact.append((fact[-1] * i) % MOD)
    return fact

def power(n, p):
    result = 1
    while p > 0:
        if p % 2 == 1:
            result = (result * n) % MOD
        n = (n * n) % MOD
        p //= 2
    return result

def combinations(n, k):
    fact = factorial(n)
    return (fact[n] * power(fact[k] * fact[n-k], MOD-2)) % MOD

def solve(K, S):
    N = len(S)
    result = 0
    for i in range(K+1):
        result = (result + combinations(N+i, i) * power(26, K-i)) % MOD
    return result

