import sys
sys.setrecursionlimit(10 ** 7)


def main():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    f = list(map(int, input().split()))

    a.sort()
    f.sort(reverse=True)

    t = [(ae, fe) for ae, fe in zip(a, f)]

    def bs(l, m, r):
        if l == m:
            return m
        cnt = 0
        for ae, fe in t:
            train = max(0, ceil((ae * fe - m) / fe))
            cnt += train

        if cnt <= k:
            l, m, r = l, (m - l) // 2 + l, m
            return bs(l, m, r)

        else:
            l, m, r = m + 1, (r - m - 1) // 2 + m + 1, r
            return bs(l, m, r)

    ans = bs(0, 10 ** 12 // 2, 10 ** 12)

    print(ans)


