from collections import defaultdict

def dfs(node, parent, graph, degree):
    for child in graph[node]:
        if child!= parent:
            degree[child] = degree[node] + 1
            if not dfs(child, node, graph, degree):
                return False
            if degree[child] % 2!= 0:
                return False
    return True

def solve(n, m, edges):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    degree = [0] * (n + 1)
    if not dfs(1, 0, graph, degree):
        return "NO"

    if m % 2!= 0:
        return "NO"

    return "YES"

