h_state = [0] * n

def water(n, h, h_state):
    for i in range(n):
        if h_state[i] < h[i]:
            l = i
            break
        elif i == n - 1 and h_state[i] < h[i]:
            l = i
        else:
            l = i + 1

    for j in range(l, n):
        if h_state[j] == h[j]:
            r = j - 1
            break
        elif j == n - 1:
            r = j

    for k in range(l, r + 1):
        h_state[k] += 1

cnt = 0
while h_state!= h:
    for i in range(n):
        if h_state[i] < h[i]:
            cnt += 1
            water(n, h, h_state)
            break
