        # 約数列挙
        divs = []
        for i in range(1, n+1):
            if i*i > n:
                break
            if n % i == 0:
                divs.append(i)
                if n//i != i:
                    # i が平方数でない
                    divs.append(n//i)
        return divs

    divs = enum_divisors(sumA)
    divs.sort(reverse=True)

    for d in divs:
        diff = []
        for a in A:
            diff.append(a % d)
        diff.sort()
        S = list(accumulate([0] + diff))
        if min(S[i] for i in range(1, N)
               if S[i] == (d * (N-i) - (S[N] - S[i]))) <= K:
