MOD = 10**9 + 7

def comb(n, k):
    if k > n - k:
        k = n - k
    result = 1
    for i in range(k):
        result = (result * (n - i)) % MOD
        result = (result * pow(i + 1, MOD - 2, MOD)) % MOD
    return result

def solve(n, k):
    result = [0] * (k + 1)
    for i in range(1, k + 1):
        result[i] = comb(n - k + i, i) * comb(k - 1, i - 1) % MOD
    return result[1:]

