MOD = 998244353

def power(n, p):
    result = 1
    while p > 0:
        if p % 2 == 1:
            result = (result * n) % MOD
        n = (n * n) % MOD
        p //= 2
    return result

def choose(n, k):
    if k > n - k:
        k = n - k
    result = 1
    for i in range(k):
        result = (result * (n - i)) % MOD
        result = (result * power(i + 1, MOD - 2)) % MOD
    return result

def solve(n, m, k):
    result = 0
    for i in range(k + 1):
        result = (result + power(m, i + 1) * choose(n - 1, i) * power(m - 1, n - i)) % MOD
    return result

n, m, k = map(int, input().split())
print(solve(n, m, k)),1,AI,CODESTRAL,medium,AIGCodeSet

