def restore_scarf_integers(a):
    n = len(a)
    result = [0] * n
    for i in range(n):
        for j in range(n):
            if i != j:
                result[i] ^= a[j]
    return result


def main():
    n = int(input())
    a = list(map(int, input().split()))
    result = restore_scarf_integers(a)
    print(*result)


